-- Hand edit: backfills.
-- C1: created_at already meant "last applied" (the replay rewrote it), so this is exact.
UPDATE "content_imports" SET "last_applied_at" = "created_at", "last_applied_by" = "imported_by";--> statement-breakpoint
-- C2: a version-1 row was never changed (every update bumps version), so its updater is its creator and its import_id is the
-- creating import; later versions lost both (sentinel / NULL).
UPDATE "content_items" SET "created_by" = CASE WHEN "version" = 1 THEN "updated_by" ELSE 'system:pre-0027' END,
	"created_import_id" = CASE WHEN "version" = 1 THEN "import_id" END;--> statement-breakpoint
-- C3: updated_at and updated_by describe the SAME latest event of this version. Events: every media_edit / media_rights audit row for
-- the version (detail.version) and its FIRST media_publish (detail.publishedVersion; a re-publish after a withdrawal never changed the
-- row, as the runtime now guarantees). Target is 'med-<id>'. With no audit event: the latest of created/published/rights-stated, by its
-- creator.
UPDATE "media_versions" v SET
	"updated_at" = GREATEST(v."created_at", v."published_at", v."rights_stated_at"),
	"updated_by" = v."created_by";--> statement-breakpoint
WITH "events" AS (
	SELECT substring(a."target" from 5)::bigint AS "media_id", (a."detail"->>'version')::integer AS "version", a."actor", a."created_at", a."id"
	FROM "admin_audit" a
	WHERE a."action" IN ('media_edit', 'media_rights') AND a."target" ~ '^med-[0-9]+$' AND a."detail"->>'version' ~ '^[0-9]+$'
	UNION ALL
	(SELECT DISTINCT ON (a."target", a."detail"->>'publishedVersion')
		substring(a."target" from 5)::bigint, (a."detail"->>'publishedVersion')::integer, a."actor", a."created_at", a."id"
	FROM "admin_audit" a
	WHERE a."action" = 'media_publish' AND a."target" ~ '^med-[0-9]+$' AND a."detail"->>'publishedVersion' ~ '^[0-9]+$'
	ORDER BY a."target", a."detail"->>'publishedVersion', a."id" ASC)
), "latest" AS (
	SELECT DISTINCT ON ("media_id", "version") "media_id", "version", "actor", "created_at"
	FROM "events" ORDER BY "media_id", "version", "created_at" DESC, "id" DESC
)
UPDATE "media_versions" v SET
	"updated_at" = GREATEST(v."created_at", v."published_at", v."rights_stated_at", l."created_at"),
	"updated_by" = l."actor"
FROM "latest" l
WHERE l."media_id" = v."media_id" AND l."version" = v."version";--> statement-breakpoint
-- C4: the latest of the request, the decision and the latest role_* audit row for this (principal, role): the audit target is the
-- principal and detail.role names the row.
UPDATE "account_roles" r SET "updated_at" = GREATEST(
	r."requested_at",
	r."decided_at",
	(SELECT max(a."created_at") FROM "admin_audit" a
		WHERE a."target" = r."principal" AND a."detail"->>'role' = r."role"
			AND a."action" IN ('role_request', 'role_approve', 'role_reject', 'role_grant', 'role_revoke', 'role_block', 'role_unblock', 'role_email_edit')));--> statement-breakpoint
-- C5: the first collection or the latest completed segment (completed Round that finished, in a completed segment) that used this Card.
UPDATE "player_clipper_cards" c SET "last_identified_at" = GREATEST(
	c."first_collected_at",
	(SELECT max(t."closed_at") FROM "rounds" ro
		JOIN "trips" t ON t."id" = ro."trip_id"
		WHERE ro."player_id" = c."player_id" AND ro."card_key" = c."card_key"
			AND t."status" = 'completed' AND ro."status" = 'completed' AND ro."finished" IS TRUE));--> statement-breakpoint
-- C6: a transient queue; the migration instant (the transaction start).
UPDATE "ugs_mirror_outbox" SET "first_enqueued_at" = now();--> statement-breakpoint
-- C7: actor of the earliest / the latest catalog audit row for the product (audit target = the bare product id), else the sentinel.
UPDATE "store_products" p SET
	"created_by" = COALESCE((SELECT a."actor" FROM "admin_audit" a
		WHERE a."target" = p."product_id" AND a."action" IN ('store_product_create', 'store_product_edit', 'store_product_retire', 'store_product_restore')
		ORDER BY a."id" ASC LIMIT 1), 'system:pre-0027'),
	"updated_by" = COALESCE((SELECT a."actor" FROM "admin_audit" a
		WHERE a."target" = p."product_id" AND a."action" IN ('store_product_create', 'store_product_edit', 'store_product_retire', 'store_product_restore')
		ORDER BY a."id" DESC LIMIT 1), 'system:pre-0027');--> statement-breakpoint

