-- Hand edit: append-only triggers, LAST (pattern of 0011 and 0024; drizzle-kit does not model triggers, so the snapshot is unaffected).
-- They guard against bugs only: the application's database role owns these tables and could disable them (ARCHITECTURE.md).
-- A test or manual cleanup that must remove rows has to DISABLE TRIGGER itself, in its own transaction.

-- Always refuses (admin_audit; every TRUNCATE trigger; used for statement triggers, which have no OLD).
CREATE FUNCTION "append_only_refuse"() RETURNS trigger LANGUAGE plpgsql AS $$
BEGIN
	RAISE EXCEPTION '% rows are append-only (% refused)', TG_TABLE_NAME, TG_OP USING ERRCODE = 'restrict_violation';
END;
$$;
--> statement-breakpoint
-- Player-owned append-only tables: UPDATE is refused; DELETE is allowed only as the ON DELETE CASCADE of the players row (account deletion).
-- The cascade runs inside the referential-integrity trigger of the DELETE FROM players (pg_trigger_depth() > 1), after that row is gone
-- from this command's view. A direct DELETE has depth 1, and so does a DELETE in the same statement as a data-modifying CTE on players.
CREATE FUNCTION "append_only_player_rows"() RETURNS trigger LANGUAGE plpgsql AS $$
BEGIN
	IF TG_OP = 'DELETE' AND pg_trigger_depth() > 1 AND NOT EXISTS (SELECT 1 FROM "players" WHERE "id" = OLD."player_id") THEN
		RETURN OLD;
	END IF;
	RAISE EXCEPTION '% rows are append-only (% refused)', TG_TABLE_NAME, TG_OP USING ERRCODE = 'restrict_violation';
END;
$$;
--> statement-breakpoint
-- A published media version is frozen: no UPDATE, no DELETE. A draft (published_at IS NULL) stays editable.
CREATE FUNCTION "media_versions_published_frozen"() RETURNS trigger LANGUAGE plpgsql AS $$
BEGIN
	IF OLD."published_at" IS NOT NULL THEN
		RAISE EXCEPTION 'published media_versions rows are immutable (% refused)', TG_OP USING ERRCODE = 'restrict_violation';
	END IF;
	IF TG_OP = 'DELETE' THEN RETURN OLD; END IF;
	RETURN NEW;
END;
$$;
--> statement-breakpoint
CREATE TRIGGER "miles_ledger_append_only" BEFORE UPDATE OR DELETE ON "miles_ledger" FOR EACH ROW EXECUTE FUNCTION "append_only_player_rows"();--> statement-breakpoint
CREATE TRIGGER "hint_ledger_append_only" BEFORE UPDATE OR DELETE ON "hint_ledger" FOR EACH ROW EXECUTE FUNCTION "append_only_player_rows"();--> statement-breakpoint
CREATE TRIGGER "store_transactions_append_only" BEFORE UPDATE OR DELETE ON "store_transactions" FOR EACH ROW EXECUTE FUNCTION "append_only_player_rows"();--> statement-breakpoint
CREATE TRIGGER "ugs_link_events_append_only" BEFORE UPDATE OR DELETE ON "ugs_link_events" FOR EACH ROW EXECUTE FUNCTION "append_only_player_rows"();--> statement-breakpoint
CREATE TRIGGER "admin_audit_append_only" BEFORE UPDATE OR DELETE ON "admin_audit" FOR EACH ROW EXECUTE FUNCTION "append_only_refuse"();--> statement-breakpoint
CREATE TRIGGER "media_versions_published_frozen" BEFORE UPDATE OR DELETE ON "media_versions" FOR EACH ROW EXECUTE FUNCTION "media_versions_published_frozen"();--> statement-breakpoint
